// Some portions generated by Claude
// Screenshot-shaped fixture (synthetic labels, not the user's data): a resource expanded into 28 neighbours that link
// nowhere else, one three-card chain hanging off it, and two separate pairs. Labels are long hash-like names, so the
// cards are about five times wider than tall.

function hashes(seed) {
  let state = seed >>> 0;
  return () => {
    let text = '';
    for (let i = 0; i < 25; i++) {
      state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
      text += (state >>> 28).toString(16);
    }
    return `${text}…`;
  };
}

export function hashHub() {
  const next = hashes(20261015);
  const nodes = [], edges = [];
  const card = () => { const id = `urn:hash:${nodes.length}`; nodes.push({ id, label: next(), kind: 'iri' }); return id; };
  const link = (source, target) => edges.push({ id: `e${edges.length}`, source, target, predicate: 'urn:parent', label: 'parent' });
  const hub = card();
  for (let i = 0; i < 28; i++) link(hub, card());
  const a = card(), b = card(), c = card();
  link(hub, a); link(b, a); link(b, c);
  for (let pair = 0; pair < 2; pair++) link(card(), card());
  return { nodes, edges, revision: 1 };
}
